import datetime
import re

from ta_moler.events.rtg.genericrtg_lineevent import GenericRtgLineEvent


class DeviceConnectionLost(GenericRtgLineEvent):
    """Device connection lost event class."""

    # Example line: Connection Manager: UESIM-MMI-CTRL-1 connection lost
    # NEW: Connection Manager: Connection lost: APP-14
    re_connection_lost = re.compile(r"Connection Manager:\s*(?P<DEVICE>.*?)\s*connection lost")
    re_connection_lost_app_devices = re.compile(r"Connection Manager:\s*Connection lost:\s*(?P<DEVICE>.*?)")
    re_connection_lost_all_devices = re.compile(
        r'Executor: Lost all connections to remote components. Halting test execution...'
    )

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for device connection lost.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(DeviceConnectionLost, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[self.re_connection_lost, self.re_connection_lost_app_devices],
            match="any"
        )


